local function run(pidx, UP, ...)
  local proto = PR[pidx]
  local code = proto[1]
  local nparam = proto[2]
  local isvar = proto[3]

  local R = {}
  local nargs = select_("#", ...)

  do
    local i = 0
    while i < nparam do
      local v = nil
      if i < nargs then v = select_(i + 1, ...) end
      R[i] = v
      i = i + 1
    end
  end

  local VARG = nil
  if isvar == 1 then
    VARG = {}
    local j = nparam + 1
    while j <= nargs do
      VARG[#VARG + 1] = select_(j, ...)
      j = j + 1
    end
  end

  local MR = nil

  local pc = 1
  local top = #code
  while pc <= top do
    local ins = code[pc]
    local op = ins[1]
    pc = pc + 1

    if op == 83 then
      R[ins[2]] = R[ins[3]]
      
    elseif op == 66 then
      R[ins[2]] = decrypt(ins[3] + 1)
      
    elseif op == 84 then
      R[ins[2]] = nil
      
    elseif op == 237 then
      R[ins[2]] = (ins[3] == 1)
      
    elseif op == 114 then
      R[ins[2]] = ENV[decrypt(ins[3] + 1)]
      
    elseif op == 178 then
      ENV[decrypt(ins[2] + 1)] = R[ins[3]]
      
    elseif op == 231 then
      local c = R[ins[3]]
      if c ~= nil then R[ins[2]] = c[1] else R[ins[2]] = nil end
      
    elseif op == 132 then
      local c = R[ins[2]]
      if c ~= nil then c[1] = R[ins[3]] else R[ins[2]] = {R[ins[3]]} end
      
    elseif op == 96 then
      R[ins[2]] = {R[ins[2]], __cell = true}
      
    elseif op == 145 then
      local c = UP[ins[3]]
      if c ~= nil then R[ins[2]] = c[1] else R[ins[2]] = nil end
      
    elseif op == 197 then
      local c = UP[ins[2]]
      if c ~= nil then c[1] = R[ins[3]] end
      
    elseif op == 130 then
      local o = R[ins[3]]
      if o ~= nil then R[ins[2]] = o[decrypt(ins[4] + 1)] else R[ins[2]] = nil end
      
    elseif op == 212 then
      local o = R[ins[2]]
      if o ~= nil then o[decrypt(ins[3] + 1)] = R[ins[4]] end
      
    elseif op == 75 then
      local o = R[ins[3]]
      if o ~= nil then R[ins[2]] = o[R[ins[4]]] else R[ins[2]] = nil end
      
    elseif op == 158 then
      local o = R[ins[2]]
      if o ~= nil then o[R[ins[3]]] = R[ins[4]] end
      
    elseif op == 97 then
      R[ins[2]] = {}
      
    elseif op == 179 then
      R[ins[2]] = R[ins[3]] + R[ins[4]]
      
    elseif op == 44 then
      R[ins[2]] = R[ins[3]] - R[ins[4]]
      
    elseif op == 122 then
      R[ins[2]] = R[ins[3]] * R[ins[4]]
      
    elseif op == 128 then
      R[ins[2]] = R[ins[3]] / R[ins[4]]
      
    elseif op == 55 then
      R[ins[2]] = R[ins[3]] % R[ins[4]]
      
    elseif op == 95 then
      R[ins[2]] = R[ins[3]] ^ R[ins[4]]
      
    elseif op == 134 then
      R[ins[2]] = R[ins[3]] // R[ins[4]]
      
    elseif op == 166 then
      R[ins[2]] = (R[ins[3]] == R[ins[4]])
      
    elseif op == 25 then
      R[ins[2]] = (R[ins[3]] ~= R[ins[4]])
      
    elseif op == 149 then
      R[ins[2]] = (R[ins[3]] < R[ins[4]])
      
    elseif op == 241 then
      R[ins[2]] = (R[ins[3]] <= R[ins[4]])
      
    elseif op == 235 then
      R[ins[2]] = (R[ins[3]] > R[ins[4]])
      
    elseif op == 28 then
      R[ins[2]] = (R[ins[3]] >= R[ins[4]])
      
    elseif op == 180 then
      R[ins[2]] = bit32 and bit32.band(R[ins[3]], R[ins[4]]) or 0
      
    elseif op == 210 then
      R[ins[2]] = bit32 and bit32.bor(R[ins[3]], R[ins[4]]) or 0
      
    elseif op == 170 then
      R[ins[2]] = bit32 and bit32.bxor(R[ins[3]], R[ins[4]]) or 0
      
    elseif op == 206 then
      R[ins[2]] = bit32 and bit32.lshift(R[ins[3]], R[ins[4]]) or 0
      
    elseif op == 101 then
      R[ins[2]] = bit32 and bit32.rshift(R[ins[3]], R[ins[4]]) or 0
      
    elseif op == 230 then
      R[ins[2]] = -R[ins[3]]
      
    elseif op == 98 then
      R[ins[2]] = not R[ins[3]]
      
    elseif op == 7 then
      R[ins[2]] = #R[ins[3]]
      
    elseif op == 191 then
      local parts = {}
      local x = 3
      while x <= #ins do
        parts[#parts + 1] = R[ins[x]]
        x = x + 1
      end
      R[ins[2]] = concat_(parts)
      
    elseif op == 16 then
      pc = ins[2] + 1
      
    elseif op == 140 then
      if not R[ins[2]] then pc = ins[3] + 1 end
      
    elseif op == 49 then
      if R[ins[2]] then pc = ins[3] + 1 end
      
    elseif op == 42 then
      if R[ins[2]] == nil then pc = ins[3] + 1 end
      
    elseif op == 236 then
      local f = R[ins[3]]
      local nres = ins[4]
      local expand = (ins[#ins] == ".")
      local stop = #ins
      if expand then stop = #ins - 1 end
      local args = {}
      local x = 5
      while x <= stop do
        args[#args + 1] = R[ins[x]]
        x = x + 1
      end
      if expand and MR ~= nil then
        local y = 1
        while y <= MR.n do
          args[#args + 1] = MR[y]
          y = y + 1
        end
      end
      if nres == 0 then
        f(unpack_(args, 1, #args))
        MR = nil
      elseif nres == 1 then
        R[ins[2]] = f(unpack_(args, 1, #args))
        MR = nil
      elseif nres < 0 then
        MR = pack_(f(unpack_(args, 1, #args)))
        MR.n = MR.n or #MR
      else
        local r = pack_(f(unpack_(args, 1, #args)))
        local y = 1
        while y <= nres do
          R[ins[2] + y - 1] = r[y]
          y = y + 1
        end
        MR = nil
      end
      
    elseif op == 194 then
      local f = R[ins[3]]
      local nres = ins[4]
      local args = {}
      local x = 5
      while x <= #ins do
        args[#args + 1] = R[ins[x]]
        x = x + 1
      end
      local r = pack_(f(unpack_(args, 1, #args)))
      local y = 1
      while y <= nres do
        R[ins[2] + y - 1] = r[y]
        y = y + 1
      end
      
    elseif op == 162 then
      if VARG == nil then VARG = {} end
      local want = ins[3]
      if want < 0 then
        MR = {n = #VARG}
        local y = 1
        while y <= #VARG do
          MR[y] = VARG[y]
          y = y + 1
        end
      else
        local y = 1
        while y <= want do
          R[ins[2] + y - 1] = VARG[y]
          y = y + 1
        end
      end
      
    elseif op == 90 then
      local pidx2 = ins[3] + 1
      local spec = PR[pidx2][5]
      local U2 = {}
      local ui = 1
      while ui <= #spec do
        local sp = spec[ui]
        if sp[1] == 0 then
          local c = R[sp[2]]
          if type_(c) ~= "table" or c.__cell ~= true then
            c = {R[sp[2]], __cell = true}
            R[sp[2]] = c
          end
          U2[ui] = c
        else
          U2[ui] = UP[sp[2]]
        end
        ui = ui + 1
      end
      R[ins[2]] = function(...) return run(pidx2, U2, ...) end
      
    elseif op == 164 then
      local n = ins[2]
      if n == nil or n == 0 then return end
      if n < 0 then
        if MR ~= nil then return unpack_(MR, 1, MR.n) end
        return
      end
      local vals = {}
      local x = 1
      while x <= n do
        vals[x] = R[ins[2 + x]]
        x = x + 1
      end
      return unpack_(vals, 1, n)
      
    elseif op == 200 then
      local nfixed = ins[2]
      local vals = {}
      local x = 1
      while x <= nfixed do
        vals[x] = R[ins[2 + x]]
        x = x + 1
      end
      if MR ~= nil then
        local y = 1
        while y <= MR.n do
          vals[nfixed + y] = MR[y]
          y = y + 1
        end
        return unpack_(vals, 1, nfixed + MR.n)
      end
      return unpack_(vals, 1, nfixed)
      
    elseif op == 64 then
      local v = R[ins[3]]
      local lim = R[ins[4]]
      local step = R[ins[5]]
      if step > 0 then
        R[ins[2]] = (v <= lim)
      else
        R[ins[2]] = (v >= lim)
      end
      
    else
      error_("vm: bad opcode")
    end
  end
end

return run(1, {}, ...)